    void ReadyPlan(int s){if(sim==null||ready[s])return;if(sim.Players[s].Credits-DraftCost(s)<floor[s]){Toast("Plan exceeds wallet or reserve. Remove a lease or lower floor.");return;}ready[s]=true;Preparation(false);if(ready.All(v=>v))LockPlans();}
